data.code:
list key {
  key "key-id";
  leaf key-id {
    type uint64;
    description "Numeric value uniquely identifying the key";
  }
  container lifetime {
    choice lifetime {
      case send-and-accept-lifetime {
        container send-accept-lifetime { uses lifetime; }
      }
      case independent-send-accept-lifetime {
        if-feature "independent-send-accept-lifetime";
        container send-lifetime   { uses lifetime; }
        container accept-lifetime { uses lifetime; }
      }
    }
  }
  leaf crypto-algorithm {
    type identityref { base crypto-algorithm; }
    mandatory true;
  }
  container key-string {
    nacm:default-deny-all;
    choice key-string-style {
      case keystring   { leaf keystring { type string; } }
      case hexadecimal { if-feature "hex-key-string";
                        leaf hexadecimal-string { type yang:hex-string; } }
    }
  }
